def pair_sum(nums, target):
    l, r = 0, len(nums) - 1
    while l < r:
        s = nums[l] + nums[r]
        if s == target:
            return [l, r]
        if s < target:
            l += 1
        else:
            r -= 1
    return []

class Solution {
    public int[] pairSum(int[] nums, int target) {
        int l = 0, r = nums.length - 1;
        while (l < r) {
            int s = nums[l] + nums[r];
            if (s == target) return new int[]{l, r};
            if (s < target) l++;
            else r--;
        }
        return new int[0];
    }
}

def is_clean_palindrome(s):
    l, r = 0, len(s) - 1
    while l < r:
        if not s[l].isalnum():
            l += 1
        elif not s[r].isalnum():
            r -= 1
        elif s[l].lower() != s[r].lower():
            return False
        else:
            l, r = l + 1, r - 1
    return True

class Solution {
    public boolean isCleanPalindrome(String s) {
        int l = 0, r = s.length() - 1;
        while (l < r) {
            if (!Character.isLetterOrDigit(s.charAt(l))) l++;
            else if (!Character.isLetterOrDigit(s.charAt(r))) r--;
            else if (Character.toLowerCase(s.charAt(l)) != Character.toLowerCase(s.charAt(r))) return false;
            else { l++; r--; }
        }
        return true;
    }
}

def reverse_chars(chars):
    l, r = 0, len(chars) - 1
    while l < r:
        chars[l], chars[r] = chars[r], chars[l]
        l, r = l + 1, r - 1

class Solution {
    public void reverseChars(char[] chars) {
        int l = 0, r = chars.length - 1;
        while (l < r) {
            char t = chars[l]; chars[l] = chars[r]; chars[r] = t;
            l++; r--;
        }
    }
}

def move_zeros(nums):
    w = 0
    for r in range(len(nums)):
        if nums[r] != 0:
            nums[w], nums[r] = nums[r], nums[w]
            w += 1

class Solution {
    public void moveZeros(int[] nums) {
        int w = 0;
        for (int r = 0; r < nums.length; r++) {
            if (nums[r] != 0) {
                int t = nums[w]; nums[w] = nums[r]; nums[r] = t;
                w++;
            }
        }
    }
}

def remove_repeats(nums):
    w = 1
    for r in range(1, len(nums)):
        if nums[r] != nums[w - 1]:
            nums[w] = nums[r]
            w += 1
    return w

class Solution {
    public int removeRepeats(int[] nums) {
        int w = 1;
        for (int r = 1; r < nums.length; r++) {
            if (nums[r] != nums[w - 1]) {
                nums[w] = nums[r];
                w++;
            }
        }
        return w;
    }
}

def keep_two(nums):
    w = 0
    for x in nums:
        if w < 2 or x != nums[w - 2]:
            nums[w] = x
            w += 1
    return w

class Solution {
    public int keepTwo(int[] nums) {
        int w = 0;
        for (int x : nums) {
            if (w < 2 || x != nums[w - 2]) {
                nums[w] = x;
                w++;
            }
        }
        return w;
    }
}

def merge_into(a, m, b, n):
    i, j, k = m - 1, n - 1, m + n - 1
    while j >= 0:
        if i >= 0 and a[i] > b[j]:
            a[k] = a[i]
            i -= 1
        else:
            a[k] = b[j]
            j -= 1
        k -= 1

class Solution {
    public void mergeInto(int[] a, int m, int[] b, int n) {
        int i = m - 1, j = n - 1, k = m + n - 1;
        while (j >= 0) {
            if (i >= 0 && a[i] > b[j]) a[k--] = a[i--];
            else a[k--] = b[j--];
        }
    }
}

def sorted_squares(nums):
    res = [0] * len(nums)
    l, r = 0, len(nums) - 1
    for k in range(len(nums) - 1, -1, -1):
        if abs(nums[l]) > abs(nums[r]):
            res[k] = nums[l] * nums[l]
            l += 1
        else:
            res[k] = nums[r] * nums[r]
            r -= 1
    return res

class Solution {
    public int[] sortedSquares(int[] nums) {
        int n = nums.length, l = 0, r = n - 1;
        int[] res = new int[n];
        for (int k = n - 1; k >= 0; k--) {
            if (Math.abs(nums[l]) > Math.abs(nums[r])) { res[k] = nums[l] * nums[l]; l++; }
            else { res[k] = nums[r] * nums[r]; r--; }
        }
        return res;
    }
}

def max_water(heights):
    l, r, best = 0, len(heights) - 1, 0
    while l < r:
        area = min(heights[l], heights[r]) * (r - l)
        best = max(best, area)
        if heights[l] < heights[r]:
            l += 1
        else:
            r -= 1
    return best

class Solution {
    public int maxWater(int[] heights) {
        int l = 0, r = heights.length - 1, best = 0;
        while (l < r) {
            int area = Math.min(heights[l], heights[r]) * (r - l);
            best = Math.max(best, area);
            if (heights[l] < heights[r]) l++;
            else r--;
        }
        return best;
    }
}

def three_sum(nums):
    nums.sort()
    res = []
    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        l, r = i + 1, len(nums) - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s < 0:
                l += 1
            elif s > 0:
                r -= 1
            else:
                res.append([nums[i], nums[l], nums[r]])
                l += 1
                while l < r and nums[l] == nums[l - 1]:
                    l += 1
    return res

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            int l = i + 1, r = nums.length - 1;
            while (l < r) {
                int s = nums[i] + nums[l] + nums[r];
                if (s < 0) l++;
                else if (s > 0) r--;
                else {
                    res.add(List.of(nums[i], nums[l], nums[r]));
                    l++;
                    while (l < r && nums[l] == nums[l - 1]) l++;
                }
            }
        }
        return res;
    }
}

def three_sum_closest(nums, target):
    nums.sort()
    best = nums[0] + nums[1] + nums[2]
    for i in range(len(nums) - 2):
        l, r = i + 1, len(nums) - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if abs(s - target) < abs(best - target):
                best = s
            if s < target:
                l += 1
            elif s > target:
                r -= 1
            else:
                return s
    return best

class Solution {
    public int threeSumClosest(int[] nums, int target) {
        Arrays.sort(nums);
        int best = nums[0] + nums[1] + nums[2];
        for (int i = 0; i < nums.length - 2; i++) {
            int l = i + 1, r = nums.length - 1;
            while (l < r) {
                int s = nums[i] + nums[l] + nums[r];
                if (Math.abs(s - target) < Math.abs(best - target)) best = s;
                if (s < target) l++;
                else if (s > target) r--;
                else return s;
            }
        }
        return best;
    }
}

def sort_colors(nums):
    lo, mid, hi = 0, 0, len(nums) - 1
    while mid <= hi:
        if nums[mid] == 0:
            nums[lo], nums[mid] = nums[mid], nums[lo]
            lo, mid = lo + 1, mid + 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[hi] = nums[hi], nums[mid]
            hi -= 1

class Solution {
    public void sortColors(int[] nums) {
        int lo = 0, mid = 0, hi = nums.length - 1;
        while (mid <= hi) {
            if (nums[mid] == 0) { int t = nums[lo]; nums[lo++] = nums[mid]; nums[mid++] = t; }
            else if (nums[mid] == 1) mid++;
            else { int t = nums[hi]; nums[hi--] = nums[mid]; nums[mid] = t; }
        }
    }
}

def trap(height):
    l, r = 0, len(height) - 1
    left_max = right_max = water = 0
    while l < r:
        if height[l] < height[r]:
            left_max = max(left_max, height[l])
            water += left_max - height[l]
            l += 1
        else:
            right_max = max(right_max, height[r])
            water += right_max - height[r]
            r -= 1
    return water

class Solution {
    public int trap(int[] height) {
        int l = 0, r = height.length - 1, leftMax = 0, rightMax = 0, water = 0;
        while (l < r) {
            if (height[l] < height[r]) {
                leftMax = Math.max(leftMax, height[l]);
                water += leftMax - height[l++];
            } else {
                rightMax = Math.max(rightMax, height[r]);
                water += rightMax - height[r--];
            }
        }
        return water;
    }
}

def is_subsequence(s, t):
    i = 0
    for j in range(len(t)):
        if i < len(s) and s[i] == t[j]:
            i += 1
    return i == len(s)

class Solution {
    public boolean isSubsequence(String s, String t) {
        int i = 0;
        for (int j = 0; j < t.length(); j++) {
            if (i < s.length() && s.charAt(i) == t.charAt(j)) i++;
        }
        return i == s.length();
    }
}

def rotate(nums, k):
    k %= len(nums)

    def reverse(l, r):
        while l < r:
            nums[l], nums[r] = nums[r], nums[l]
            l, r = l + 1, r - 1

    reverse(0, len(nums) - 1)
    reverse(0, k - 1)
    reverse(k, len(nums) - 1)

class Solution {
    public void rotate(int[] nums, int k) {
        k %= nums.length;
        reverse(nums, 0, nums.length - 1);
        reverse(nums, 0, k - 1);
        reverse(nums, k, nums.length - 1);
    }

    private void reverse(int[] a, int l, int r) {
        while (l < r) { int t = a[l]; a[l++] = a[r]; a[r--] = t; }
    }
}

def min_boats(people, limit):
    people.sort()
    l, r, boats = 0, len(people) - 1, 0
    while l <= r:
        if people[l] + people[r] <= limit:
            l += 1
        boats += 1
        r -= 1
    return boats

class Solution {
    public int minBoats(int[] people, int limit) {
        Arrays.sort(people);
        int l = 0, r = people.length - 1, boats = 0;
        while (l <= r) {
            if (people[l] + people[r] <= limit) l++;
            boats++;
            r--;
        }
        return boats;
    }
}

def almost_palindrome(s):
    def is_pal(l, r):
        while l < r:
            if s[l] != s[r]:
                return False
            l, r = l + 1, r - 1
        return True

    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            return is_pal(l + 1, r) or is_pal(l, r - 1)
        l, r = l + 1, r - 1
    return True

class Solution {
    public boolean almostPalindrome(String s) {
        int l = 0, r = s.length() - 1;
        while (l < r) {
            if (s.charAt(l) != s.charAt(r)) return isPal(s, l + 1, r) || isPal(s, l, r - 1);
            l++; r--;
        }
        return true;
    }

    private boolean isPal(String s, int l, int r) {
        while (l < r) if (s.charAt(l++) != s.charAt(r--)) return false;
        return true;
    }
}

def reverse_vowels(s):
    chars, vowels = list(s), set("aeiouAEIOU")
    l, r = 0, len(chars) - 1
    while l < r:
        if chars[l] not in vowels:
            l += 1
        elif chars[r] not in vowels:
            r -= 1
        else:
            chars[l], chars[r] = chars[r], chars[l]
            l, r = l + 1, r - 1
    return "".join(chars)

class Solution {
    public String reverseVowels(String s) {
        char[] c = s.toCharArray();
        String vowels = "aeiouAEIOU";
        int l = 0, r = c.length - 1;
        while (l < r) {
            if (vowels.indexOf(c[l]) < 0) l++;
            else if (vowels.indexOf(c[r]) < 0) r--;
            else { char t = c[l]; c[l++] = c[r]; c[r--] = t; }
        }
        return new String(c);
    }
}

def backspace_equal(s, t):
    def survivor(x, i):
        skip = 0
        while i >= 0:
            if x[i] == "#":
                skip += 1
            elif skip:
                skip -= 1
            else:
                break
            i -= 1
        return i

    i, j = len(s) - 1, len(t) - 1
    while True:
        i, j = survivor(s, i), survivor(t, j)
        if i < 0 or j < 0:
            return i < 0 and j < 0
        if s[i] != t[j]:
            return False
        i, j = i - 1, j - 1

class Solution {
    public boolean backspaceEqual(String s, String t) {
        int i = s.length() - 1, j = t.length() - 1;
        while (true) {
            i = survivor(s, i); j = survivor(t, j);
            if (i < 0 || j < 0) return i < 0 && j < 0;
            if (s.charAt(i) != t.charAt(j)) return false;
            i--; j--;
        }
    }

    private int survivor(String x, int i) {
        int skip = 0;
        for (; i >= 0; i--) {
            if (x.charAt(i) == '#') skip++;
            else if (skip > 0) skip--;
            else break;
        }
        return i;
    }
}

def next_arrangement(nums):
    i = len(nums) - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i >= 0:
        j = len(nums) - 1
        while nums[j] <= nums[i]:
            j -= 1
        nums[i], nums[j] = nums[j], nums[i]
    l, r = i + 1, len(nums) - 1
    while l < r:
        nums[l], nums[r] = nums[r], nums[l]
        l, r = l + 1, r - 1

class Solution {
    public void nextArrangement(int[] nums) {
        int i = nums.length - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) i--;
        if (i >= 0) {
            int j = nums.length - 1;
            while (nums[j] <= nums[i]) j--;
            int t = nums[i]; nums[i] = nums[j]; nums[j] = t;
        }
        for (int l = i + 1, r = nums.length - 1; l < r; l++, r--) {
            int t = nums[l]; nums[l] = nums[r]; nums[r] = t;
        }
    }
}

def find_duplicate(nums):
    slow = fast = nums[0]
    while True:
        slow, fast = nums[slow], nums[nums[fast]]
        if slow == fast:
            break
    slow = nums[0]
    while slow != fast:
        slow, fast = nums[slow], nums[fast]
    return slow

class Solution {
    public int findDuplicate(int[] nums) {
        int slow = nums[0], fast = nums[0];
        do { slow = nums[slow]; fast = nums[nums[fast]]; } while (slow != fast);
        slow = nums[0];
        while (slow != fast) { slow = nums[slow]; fast = nums[fast]; }
        return slow;
    }
}

def common_values(a, b):
    i = j = 0
    res = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            res.append(a[i])
            i, j = i + 1, j + 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return res

class Solution {
    public List<Integer> commonValues(int[] a, int[] b) {
        List<Integer> res = new ArrayList<>();
        int i = 0, j = 0;
        while (i < a.length && j < b.length) {
            if (a[i] == b[j]) { res.add(a[i]); i++; j++; }
            else if (a[i] < b[j]) i++;
            else j++;
        }
        return res;
    }
}

def longest_unique(s):
    last, l, best = {}, 0, 0
    for r, ch in enumerate(s):
        if last.get(ch, -1) >= l:
            l = last[ch] + 1
        last[ch] = r
        best = max(best, r - l + 1)
    return best

class Solution {
    public int longestUnique(String s) {
        Map<Character, Integer> last = new HashMap<>();
        int l = 0, best = 0;
        for (int r = 0; r < s.length(); r++) {
            char ch = s.charAt(r);
            if (last.getOrDefault(ch, -1) >= l) l = last.get(ch) + 1;
            last.put(ch, r);
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

class Solution {
    public int bestWindowSum(int[] nums, int k) {
        int window = 0;
        for (int i = 0; i < k; i++) window += nums[i];
        int best = window;
        for (int r = k; r < nums.length; r++) {
            window += nums[r] - nums[r - k];
            best = Math.max(best, window);
        }
        return best;
    }
}

def shortest_at_least(target, nums):
    l, total, best = 0, 0, float("inf")
    for r, x in enumerate(nums):
        total += x
        while total >= target:
            best = min(best, r - l + 1)
            total -= nums[l]
            l += 1
    return 0 if best == float("inf") else best

class Solution {
    public int shortestAtLeast(int target, int[] nums) {
        int l = 0, total = 0, best = Integer.MAX_VALUE;
        for (int r = 0; r < nums.length; r++) {
            total += nums[r];
            while (total >= target) {
                best = Math.min(best, r - l + 1);
                total -= nums[l++];
            }
        }
        return best == Integer.MAX_VALUE ? 0 : best;
    }
}

def longest_after_changes(s, k):
    count, l, top, best = {}, 0, 0, 0
    for r, ch in enumerate(s):
        count[ch] = count.get(ch, 0) + 1
        top = max(top, count[ch])
        if r - l + 1 - top > k:
            count[s[l]] -= 1
            l += 1
        best = max(best, r - l + 1)
    return best

class Solution {
    public int longestAfterChanges(String s, int k) {
        int[] count = new int[26];
        int l = 0, top = 0, best = 0;
        for (int r = 0; r < s.length(); r++) {
            top = Math.max(top, ++count[s.charAt(r) - 'A']);
            if (r - l + 1 - top > k) count[s.charAt(l++) - 'A']--;
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

def contains_permutation(p, s):
    if len(p) > len(s):
        return False
    need, have = [0] * 26, [0] * 26
    for ch in p:
        need[ord(ch) - 97] += 1
    for r, ch in enumerate(s):
        have[ord(ch) - 97] += 1
        if r >= len(p):
            have[ord(s[r - len(p)]) - 97] -= 1
        if have == need:
            return True
    return False

class Solution {
    public boolean containsPermutation(String p, String s) {
        if (p.length() > s.length()) return false;
        int[] need = new int[26], have = new int[26];
        for (char c : p.toCharArray()) need[c - 'a']++;
        for (int r = 0; r < s.length(); r++) {
            have[s.charAt(r) - 'a']++;
            if (r >= p.length()) have[s.charAt(r - p.length()) - 'a']--;
            if (Arrays.equals(have, need)) return true;
        }
        return false;
    }
}

def anagram_starts(s, p):
    need, have, res = [0] * 26, [0] * 26, []
    for ch in p:
        need[ord(ch) - 97] += 1
    for r, ch in enumerate(s):
        have[ord(ch) - 97] += 1
        if r >= len(p):
            have[ord(s[r - len(p)]) - 97] -= 1
        if have == need:
            res.append(r - len(p) + 1)
    return res

class Solution {
    public List<Integer> anagramStarts(String s, String p) {
        int[] need = new int[26], have = new int[26];
        List<Integer> res = new ArrayList<>();
        for (char c : p.toCharArray()) need[c - 'a']++;
        for (int r = 0; r < s.length(); r++) {
            have[s.charAt(r) - 'a']++;
            if (r >= p.length()) have[s.charAt(r - p.length()) - 'a']--;
            if (Arrays.equals(have, need)) res.add(r - p.length() + 1);
        }
        return res;
    }
}

from collections import Counter

def min_window(s, t):
    need, missing = Counter(t), len(t)
    l = start = 0
    best = float("inf")
    for r, ch in enumerate(s):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1
        while missing == 0:
            if r - l + 1 < best:
                best, start = r - l + 1, l
            need[s[l]] += 1
            if need[s[l]] > 0:
                missing += 1
            l += 1
    return "" if best == float("inf") else s[start:start + best]

class Solution {
    public String minWindow(String s, String t) {
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;
        int missing = t.length(), l = 0, start = 0, best = Integer.MAX_VALUE;
        for (int r = 0; r < s.length(); r++) {
            if (need[s.charAt(r)]-- > 0) missing--;
            while (missing == 0) {
                if (r - l + 1 < best) { best = r - l + 1; start = l; }
                if (++need[s.charAt(l++)] > 0) missing++;
            }
        }
        return best == Integer.MAX_VALUE ? "" : s.substring(start, start + best);
    }
}

def longest_ones(nums, k):
    l = zeros = best = 0
    for r, x in enumerate(nums):
        zeros += x == 0
        while zeros > k:
            zeros -= nums[l] == 0
            l += 1
        best = max(best, r - l + 1)
    return best

class Solution {
    public int longestOnes(int[] nums, int k) {
        int l = 0, zeros = 0, best = 0;
        for (int r = 0; r < nums.length; r++) {
            if (nums[r] == 0) zeros++;
            while (zeros > k) if (nums[l++] == 0) zeros--;
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

def two_baskets(fruits):
    count, l, best = {}, 0, 0
    for r, f in enumerate(fruits):
        count[f] = count.get(f, 0) + 1
        while len(count) > 2:
            count[fruits[l]] -= 1
            if count[fruits[l]] == 0:
                del count[fruits[l]]
            l += 1
        best = max(best, r - l + 1)
    return best

class Solution {
    public int twoBaskets(int[] fruits) {
        Map<Integer, Integer> count = new HashMap<>();
        int l = 0, best = 0;
        for (int r = 0; r < fruits.length; r++) {
            count.merge(fruits[r], 1, Integer::sum);
            while (count.size() > 2) {
                if (count.merge(fruits[l], -1, Integer::sum) == 0) count.remove(fruits[l]);
                l++;
            }
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

def longest_k_distinct(s, k):
    count, l, best = {}, 0, 0
    for r, ch in enumerate(s):
        count[ch] = count.get(ch, 0) + 1
        while len(count) > k:
            count[s[l]] -= 1
            if count[s[l]] == 0:
                del count[s[l]]
            l += 1
        best = max(best, r - l + 1)
    return best

class Solution {
    public int longestKDistinct(String s, int k) {
        Map<Character, Integer> count = new HashMap<>();
        int l = 0, best = 0;
        for (int r = 0; r < s.length(); r++) {
            count.merge(s.charAt(r), 1, Integer::sum);
            while (count.size() > k) {
                char c = s.charAt(l++);
                if (count.merge(c, -1, Integer::sum) == 0) count.remove(c);
            }
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

def count_small_products(nums, k):
    if k <= 1:
        return 0
    prod, l, count = 1, 0, 0
    for r, x in enumerate(nums):
        prod *= x
        while prod >= k:
            prod //= nums[l]
            l += 1
        count += r - l + 1
    return count

class Solution {
    public int countSmallProducts(int[] nums, int k) {
        if (k <= 1) return 0;
        long prod = 1;
        int l = 0, count = 0;
        for (int r = 0; r < nums.length; r++) {
            prod *= nums[r];
            while (prod >= k) prod /= nums[l++];
            count += r - l + 1;
        }
        return count;
    }
}

from collections import deque

def window_maxes(nums, k):
    dq, res = deque(), []
    for r, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(r)
        if dq[0] <= r - k:
            dq.popleft()
        if r >= k - 1:
            res.append(nums[dq[0]])
    return res

class Solution {
    public int[] windowMaxes(int[] nums, int k) {
        Deque<Integer> dq = new ArrayDeque<>();
        int[] res = new int[nums.length - k + 1];
        for (int r = 0; r < nums.length; r++) {
            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[r]) dq.pollLast();
            dq.addLast(r);
            if (dq.peekFirst() <= r - k) dq.pollFirst();
            if (r >= k - 1) res[r - k + 1] = nums[dq.peekFirst()];
        }
        return res;
    }
}

def max_profit(prices):
    buy, best = 0, 0
    for sell in range(1, len(prices)):
        if prices[sell] < prices[buy]:
            buy = sell
        else:
            best = max(best, prices[sell] - prices[buy])
    return best

class Solution {
    public int maxProfit(int[] prices) {
        int buy = 0, best = 0;
        for (int sell = 1; sell < prices.length; sell++) {
            if (prices[sell] < prices[buy]) buy = sell;
            else best = Math.max(best, prices[sell] - prices[buy]);
        }
        return best;
    }
}

def nearby_duplicate(nums, k):
    window = set()
    for r, x in enumerate(nums):
        if x in window:
            return True
        window.add(x)
        if len(window) > k:
            window.remove(nums[r - k])
    return False

class Solution {
    public boolean nearbyDuplicate(int[] nums, int k) {
        Set<Integer> window = new HashSet<>();
        for (int r = 0; r < nums.length; r++) {
            if (!window.add(nums[r])) return true;
            if (window.size() > k) window.remove(nums[r - k]);
        }
        return false;
    }
}

def most_vowels(s, k):
    count = best = 0
    for r, ch in enumerate(s):
        count += ch in "aeiou"
        if r >= k:
            count -= s[r - k] in "aeiou"
        best = max(best, count)
    return best

class Solution {
    public int mostVowels(String s, int k) {
        String v = "aeiou";
        int count = 0, best = 0;
        for (int r = 0; r < s.length(); r++) {
            if (v.indexOf(s.charAt(r)) >= 0) count++;
            if (r >= k && v.indexOf(s.charAt(r - k)) >= 0) count--;
            best = Math.max(best, count);
        }
        return best;
    }
}

def best_contiguous(nums):
    best, cur, l = nums[0], 0, 0
    for r, x in enumerate(nums):
        if cur < 0:
            cur, l = 0, r
        cur += x
        best = max(best, cur)
    return best

class Solution {
    public int bestContiguous(int[] nums) {
        int best = nums[0], cur = 0;
        for (int x : nums) {
            if (cur < 0) cur = 0;
            cur += x;
            best = Math.max(best, cur);
        }
        return best;
    }
}

class Solution {
    public int cardPoints(int[] cards, int k) {
        int total = 0, n = cards.length;
        for (int i = 0; i < k; i++) total += cards[i];
        int best = total;
        for (int i = 1; i <= k; i++) {
            total += cards[n - i] - cards[k - i];
            best = Math.max(best, total);
        }
        return best;
    }
}

def max_frequency(nums, k):
    nums.sort()
    l = total = best = 0
    for r, x in enumerate(nums):
        total += x
        while x * (r - l + 1) - total > k:
            total -= nums[l]
            l += 1
        best = max(best, r - l + 1)
    return best

class Solution {
    public int maxFrequency(int[] nums, int k) {
        Arrays.sort(nums);
        long total = 0;
        int l = 0, best = 0;
        for (int r = 0; r < nums.length; r++) {
            total += nums[r];
            while ((long) nums[r] * (r - l + 1) - total > k) total -= nums[l++];
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

def exactly_k_odd(nums, k):
    def at_most(k):
        l = count = odd = 0
        for r, x in enumerate(nums):
            odd += x % 2
            while odd > k:
                odd -= nums[l] % 2
                l += 1
            count += r - l + 1
        return count

    return at_most(k) - at_most(k - 1)

class Solution {
    public int exactlyKOdd(int[] nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);
    }

    private int atMost(int[] nums, int k) {
        int l = 0, count = 0, odd = 0;
        for (int r = 0; r < nums.length; r++) {
            odd += nums[r] % 2;
            while (odd > k) odd -= nums[l++] % 2;
            count += r - l + 1;
        }
        return count;
    }
}

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            Integer j = seen.get(target - nums[i]);
            if (j != null) return new int[]{j, i};
            seen.put(nums[i], i);
        }
        return new int[0];
    }
}

def two_sum(nums, target):
    idx = sorted(range(len(nums)), key=lambda i: nums[i])
    l, r = 0, len(nums) - 1
    while l < r:
        s = nums[idx[l]] + nums[idx[r]]
        if s == target:
            return sorted([idx[l], idx[r]])
        if s < target:
            l += 1
        else:
            r -= 1
    return []

class Solution {
    public int[] twoSum(int[] nums, int target) {
        Integer[] idx = new Integer[nums.length];
        for (int i = 0; i < idx.length; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(nums[a], nums[b]));
        int l = 0, r = nums.length - 1;
        while (l < r) {
            int s = nums[idx[l]] + nums[idx[r]];
            if (s == target) return new int[]{Math.min(idx[l], idx[r]), Math.max(idx[l], idx[r])};
            if (s < target) l++; else r--;
        }
        return new int[0];
    }
}

def has_repeat(nums):
