def same_letters(s, t):
    if len(s) != len(t):
        return False
    count = [0] * 26
    for a, b in zip(s, t):
        count[ord(a) - 97] += 1
        count[ord(b) - 97] -= 1
    return all(c == 0 for c in count)

class Solution {
    public boolean sameLetters(String s, String t) {
        if (s.length() != t.length()) return false;
        int[] count = new int[26];
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
            count[t.charAt(i) - 'a']--;
        }
        for (int c : count) if (c != 0) return false;
        return true;
    }
}

def group_anagrams(words):
    groups = {}
    for w in words:
        key = "".join(sorted(w))
        groups.setdefault(key, []).append(w)
    return list(groups.values())

class Solution {
    public List<List<String>> groupAnagrams(String[] words) {
        Map<String, List<String>> groups = new HashMap<>();
        for (String w : words) {
            char[] c = w.toCharArray();
            Arrays.sort(c);
            groups.computeIfAbsent(new String(c), x -> new ArrayList<>()).add(w);
        }
        return new ArrayList<>(groups.values());
    }
}

from collections import Counter

def top_k_frequent(nums, k):
    count = Counter(nums)
    buckets = [[] for _ in range(len(nums) + 1)]
    for x, c in count.items():
        buckets[c].append(x)
    res = []
    for c in range(len(nums), 0, -1):
        for x in buckets[c]:
            res.append(x)
            if len(res) == k:
                return res
    return res

class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : nums) count.merge(x, 1, Integer::sum);
        List<List<Integer>> buckets = new ArrayList<>();
        for (int i = 0; i <= nums.length; i++) buckets.add(new ArrayList<>());
        count.forEach((x, c) -> buckets.get(c).add(x));
        int[] res = new int[k];
        int n = 0;
        for (int c = nums.length; c > 0 && n < k; c--)
            for (int x : buckets.get(c)) if (n < k) res[n++] = x;
        return res;
    }
}

class Solution {
    public int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        for (int i = 0, left = 1; i < n; left *= nums[i++]) res[i] = left;
        for (int i = n - 1, right = 1; i >= 0; right *= nums[i--]) res[i] *= right;
        return res;
    }
}

def longest_run(nums):
    s, best = set(nums), 0
    for x in s:
        if x - 1 not in s:
            length = 1
            while x + length in s:
                length += 1
            best = max(best, length)
    return best

class Solution {
    public int longestRun(int[] nums) {
        Set<Integer> s = new HashSet<>();
        for (int x : nums) s.add(x);
        int best = 0;
        for (int x : s) {
            if (s.contains(x - 1)) continue;
            int length = 1;
            while (s.contains(x + length)) length++;
            best = Math.max(best, length);
        }
        return best;
    }
}

def majority(nums):
    candidate, votes = None, 0
    for i, x in enumerate(nums):
        if votes == 0:
            candidate = x
        votes += 1 if x == candidate else -1
    return candidate

class Solution {
    public int majority(int[] nums) {
        int candidate = 0, votes = 0;
        for (int x : nums) {
            if (votes == 0) candidate = x;
            votes += x == candidate ? 1 : -1;
        }
        return candidate;
    }
}

from collections import Counter

def first_unique(s):
