def same_shape(s, t):
    fwd, back = {}, {}
    for i, (a, b) in enumerate(zip(s, t)):
        if fwd.get(a, b) != b or back.get(b, a) != a:
            return False
        fwd[a], back[b] = b, a
    return True

class Solution {
    public boolean sameShape(String s, String t) {
        Map<Character, Character> fwd = new HashMap<>(), back = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char a = s.charAt(i), b = t.charAt(i);
            if (fwd.getOrDefault(a, b) != b || back.getOrDefault(b, a) != a) return false;
            fwd.put(a, b); back.put(b, a);
        }
        return true;
    }
}

def can_build(note, magazine):
    count = [0] * 26
    for ch in magazine:
        count[ord(ch) - 97] += 1
    for ch in note:
        count[ord(ch) - 97] -= 1
        if count[ord(ch) - 97] < 0:
            return False
    return True

class Solution {
    public boolean canBuild(String note, String magazine) {
        int[] count = new int[26];
        for (char c : magazine.toCharArray()) count[c - 'a']++;
        for (char c : note.toCharArray()) {
            count[c - 'a']--;
            if (count[c - 'a'] < 0) return false;
        }
        return true;
    }
}

def first_missing_positive(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1
            nums[i], nums[j] = nums[j], nums[i]
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

class Solution {
    public int firstMissingPositive(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {
                int j = nums[i] - 1, t = nums[j]; nums[j] = nums[i]; nums[i] = t;
            }
        }
        for (int i = 0; i < n; i++) if (nums[i] != i + 1) return i + 1;
        return n + 1;
    }
}

class RangeSum:
    def __init__(self, nums):
        self.prefix = [0]
        for x in nums:
            self.prefix.append(self.prefix[-1] + x)

    def query(self, l, r):
        return self.prefix[r + 1] - self.prefix[l]

class RangeSum {
    private final int[] prefix;

    RangeSum(int[] nums) {
        prefix = new int[nums.length + 1];
        for (int i = 0; i < nums.length; i++) prefix[i + 1] = prefix[i] + nums[i];
    }

    public int query(int l, int r) {
        return prefix[r + 1] - prefix[l];
    }
}

class Solution {
    public int countSumK(int[] nums, int k) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);
        int prefix = 0, count = 0;
        for (int x : nums) {
            prefix += x;
            count += seen.getOrDefault(prefix - k, 0);
            seen.merge(prefix, 1, Integer::sum);
        }
        return count;
    }
}

def balance_index(nums):
    total, left = sum(nums), 0
    for i, x in enumerate(nums):
        if left == total - left - x:
            return i
        left += x
    return -1

class Solution {
    public int balanceIndex(int[] nums) {
        int total = 0, left = 0;
        for (int x : nums) total += x;
        for (int i = 0; i < nums.length; i++) {
            if (left == total - left - nums[i]) return i;
            left += nums[i];
        }
        return -1;
    }
}

def longest_equal(nums):
    first, bal, best = {0: -1}, 0, 0
    for i, x in enumerate(nums):
        bal += 1 if x == 1 else -1
        if bal in first:
            best = max(best, i - first[bal])
        else:
            first[bal] = i
    return best

class Solution {
    public int longestEqual(int[] nums) {
        Map<Integer, Integer> first = new HashMap<>();
        first.put(0, -1);
        int bal = 0, best = 0;
        for (int i = 0; i < nums.length; i++) {
            bal += nums[i] == 1 ? 1 : -1;
            if (first.containsKey(bal)) best = Math.max(best, i - first.get(bal));
            else first.put(bal, i);
        }
        return best;
    }
}

class Solution {
    public int divisibleRuns(int[] nums, int k) {
        int[] seen = new int[k];
        seen[0] = 1;
        int rem = 0, count = 0;
        for (int x : nums) {
            rem = ((rem + x) % k + k) % k;
            count += seen[rem]++;
        }
        return count;
    }
}

def seat_totals(bookings, n):
    diff = [0] * (n + 1)
    for first, last, seats in bookings:
        diff[first - 1] += seats
        diff[last] -= seats
    res, running = [], 0
    for i in range(n):
        running += diff[i]
        res.append(running)
    return res

class Solution {
    public int[] seatTotals(int[][] bookings, int n) {
        int[] diff = new int[n + 1];
        for (int[] b : bookings) { diff[b[0] - 1] += b[2]; diff[b[1]] -= b[2]; }
        int[] res = new int[n];
        for (int i = 0, running = 0; i < n; i++) res[i] = running += diff[i];
        return res;
    }
}

def search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

class Solution {
    public int search(int[] nums, int target) {
        int lo = 0, hi = nums.length - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (nums[mid] == target) return mid;
            if (nums[mid] < target) lo = mid + 1;
            else hi = mid - 1;
        }
        return -1;
    }
}

def insert_position(nums, target):
